public class VolumePanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            VolumePanel panel = new VolumePanel();
            java.awt.Component sliderC = find(panel, "volume");
            java.awt.Component label = find(panel, "readout");
            check("readout starts at 50", "50", textOf(label));
            if (sliderC instanceof javax.swing.JSlider) {
                javax.swing.JSlider slider = (javax.swing.JSlider) sliderC;
                check("slider starts at 50", 50, slider.getValue());
                slider.setValue(75);
                check("readout follows slider to 75", "75", textOf(label));
                slider.setValue(0);
                check("readout at minimum", "0", textOf(label));
                slider.setValue(100);
                check("readout at maximum", "100", textOf(label));
                slider.setValue(33);
                check("readout follows slider to 33", "33", textOf(label));
            } else {
                failures++;
                System.out.println("FAIL  slider not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

