import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;

public class VolumePanel extends JPanel {

    private final JSlider volume = new JSlider(0, 100, 50);
    private final JLabel readout = new JLabel("50");

    public VolumePanel() {
        volume.setName("volume");
        readout.setName("readout");
        add(volume);
        add(readout);
        volume.addChangeListener(e -> readout.setText(String.valueOf(volume.getValue())));
    }
}
